import os
import openai
from typing import List, Dict, Any
from embeddings_models import EmbeddingRequest, EmbeddingResponse

class EmbeddingsClient:
    def __init__(self):
        self.client = openai.OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    def get_embeddings(self, texts: List[str], model: str) -> EmbeddingResponse:
        response = self.client.embeddings.create(input=texts, model=model)
        return EmbeddingResponse(
            object=response.object,
            data=[item.model_dump() for item in response.data],
            model=response.model,
            usage=response.usage.model_dump()
        )

import numpy as np
from typing import List

def cosine_similarity(embedding1: List[float], embedding2: List[float]) -> float:
    vec1 = np.array(embedding1)
    vec2 = np.array(embedding2)
    similarity = np.dot(vec1, vec2) / (np.linalg.norm(vec1) * np.linalg.norm(vec2))
    return float(similarity)

def similarity_score(text1_embedding: List[float], text2_embedding: List[float]) -> float:
    return cosine_similarity(text1_embedding, text2_embedding)

import openai
import os
from typing import List, Dict, Any

def check_corpus_safety(texts: List[str]) -> Dict[str, Any]:
    client = openai.OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    moderation_results = client.moderations.create(input=texts)

    # The moderation API returns results for each text in the input list
    # We can process these results to check for any unsafe content
    safety_report = {"flagged": False, "categories": {}}
    for result in moderation_results.results:
        if result.flagged:
            safety_report["flagged"] = True
            for category, is_flagged in result.categories.model_dump().items():
                if is_flagged:
                    safety_report["categories"][category] = True

    return safety_report

import openai
import os
from typing import List

def translate_query(query: str, target_language: str = "English") -> str:
    client = openai.OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    translation_prompt = f"Translate the following text to {target_language}: '{query}'"

    response = client.chat.completions.create(
        model="gpt-3.5-turbo",
        messages=[
            {"role": "system", "content": "You are a helpful assistant that translates text."},
            {"role": "user", "content": translation_prompt}
        ],
        max_tokens=100
    )
    return response.choices[0].message.content.strip()

def multilingual_query_translate(query: str, target_languages: List[str]) -> Dict[str, str]:
    translated_queries = {}
    for lang in target_languages:
        translated_queries[lang] = translate_query(query, lang)
    return translated_queries
